"""Generates warmup_unblock_01_results.html (source: _results.md)."""
import os
def attribution_bar():
    # single horizontal composition bar: BN ~30% / gradient ~70% of T60/EDT damage
    W,H,LM = 720,120,20; PW=W-2*LM
    s=[f'<svg viewBox="0 0 {W} {H}" role="img" aria-label="damage attribution">']
    w1 = 0.30*PW; w2 = 0.70*PW - 2
    s.append(f'<rect class="mark" x="{LM}" y="40" width="{w1:.0f}" height="26" rx="4" fill="var(--s2)"><title>BN/data-statistics channel: ~30% (proven by W0, lr=0)</title></rect>')
    s.append(f'<rect class="mark" x="{LM+w1+2:.0f}" y="40" width="{w2:.0f}" height="26" rx="4" fill="var(--s1)"><title>Gradient adaptation toward the drifted optimum: ~70% (R1b ≡ W1)</title></rect>')
    s.append(f'<text class="val" x="{LM+w1/2:.0f}" y="57" text-anchor="middle" fill="#fff">BN ~30%</text>')
    s.append(f'<text class="val" x="{LM+w1+2+w2/2:.0f}" y="57" text-anchor="middle" fill="#fff">gradient path ~70%</text>')
    s.append(f'<text x="{LM}" y="20" class="val">T60/EDT fine-tune damage — mechanism shares (exp_03+04 combined evidence)</text>')
    s.append(f'<text x="{LM}" y="90">W0 (lr=0, only BN buffers mutable) reproduced ~30% of the damage with zero gradient steps → data-statistics drift proven gradient-free.</text>')
    s.append('</svg>'); return "".join(s)
html = f"""<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>exp_04 — warmup test & null control</title><link rel="stylesheet" href="warmup_unblock_results_assets/results.css"></head><body>
<h1>exp_04 — Adam-transient test (falsified) & the lr=0 null control (the real discovery)</h1>
<p class="sub">Full split · 5 seeds per eval · gates = exp_01 · 2026-07-05/06. Numbers mirror <a href="warmup_unblock_results.md">_results.md</a>.</p>
<h2>W1 — warmup control (lr 0→5e-6 over 200 steps): <span class="chip fail">✗ GATE FAIL</span></h2>
<table><thead><tr><th>K</th><th class="num">T60</th><th class="num">C50</th><th class="num">EDT</th><th class="num">R@1</th><th class="num">Δ vs R1b (no warmup)</th></tr></thead><tbody>
<tr><td>1</td><td class="num">10.485 (6.4σ)</td><td class="num">1.077 (2.6σ)</td><td class="num">42.96 (7.2σ)</td><td class="num">6.81 <span class="chip pass">✓</span></td><td class="num">ΔT60 +0.02 · ΔEDT −0.31</td></tr>
<tr><td>8</td><td class="num">9.206 (39.6σ)</td><td class="num">0.994 (5.9σ)</td><td class="num">40.17 (36.5σ)</td><td class="num">7.09 <span class="chip pass">✓</span></td><td class="num">ΔT60 +0.01 · ΔEDT −0.34</td></tr></tbody></table>
<div class="verdict bad"><b>Adam-transient hypothesis falsified.</b> The warmup demonstrably engaged (probe-verified exact lr ramp) and changed <i>nothing</i> — W1 ≡ R1b within seed noise. Two differently-conditioned runs converge to the same regressed optimum: the destination, not the optimizer, is the problem.</div>
<h2>W0 — lr=0 null control: <span class="chip fail">✗ FAIL — and that falsification is the finding</span></h2>
<table><thead><tr><th>K</th><th class="num">T60</th><th class="num">C50</th><th class="num">EDT</th><th class="num">R@1</th></tr></thead><tbody>
<tr><td>1</td><td class="num">10.132 (2.4σ)</td><td class="num"><b>1.050 (0.4σ ✓)</b></td><td class="num">41.10 (3.0σ)</td><td class="num">6.58 ✓</td></tr>
<tr><td>8</td><td class="num">8.823 (15.4σ)</td><td class="num"><b>0.966 (0.6σ ✓)</b></td><td class="num">38.39 (19.0σ)</td><td class="num">6.88 ✓</td></tr></tbody></table>
<div class="verdict mixed"><b>Data-pipeline drift proven without a single gradient step.</b> At lr=0 only the RIR-encoder BatchNorm running statistics can move; they moved enough to cost ~30% of the full T60/EDT damage. BN buffers drift only when incoming statistics differ from the stored ones ⇒ our loader's reference-RIR statistics ≠ those the released training saw.</div>
<h2>Attribution ledger</h2>
<figure>{attribution_bar()}</figure>
<table><thead><tr><th>Mechanism</th><th>Evidence</th><th>Share / status</th></tr></thead><tbody>
<tr><td>Data-statistics drift via BN</td><td>W0 regression at lr=0</td><td><span class="chip warnc">~30%</span></td></tr>
<tr><td>Gradient adaptation to drifted optimum</td><td>R1b ≡ W1 (warmup-independent)</td><td><span class="chip warnc">~70%</span></td></tr>
<tr><td>Adam second-moment transient</td><td>W1 ≡ R1b</td><td><span class="chip fail">dead</span></td></tr>
<tr><td>EMA-vs-online</td><td>exp_03 corrected diagnostic</td><td><span class="chip info">≤15% (subsumed)</span></td></tr>
<tr><td>Batch noise (sole cause)</td><td>R1→R1b delta</td><td><span class="chip info">partial, insufficient</span></td></tr>
<tr><td>lr magnitude</td><td>8× below original final lr</td><td><span class="chip info">excluded (see exp_06)</span></td></tr></tbody></table>
<p>Signature throughout: energy-decay metrics damaged; retrieval never. Registered stop honored: W2–W4b not run.</p>
<p class="foot">Generated by <code>warmup_unblock_results_assets/gen_page.py</code>.</p>
</body></html>"""
out = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'warmup_unblock_01_results.html')
open(out,'w').write(html); print('wrote', out)
